      int from = first.charAt(index) - 'a';
      int to = second.charAt(index) - 'a';
      if ((forward[from] >= 0 && forward[from] != to) || (backward[to] >= 0 && backward[to] != from)) return false;
      forward[from] = to;
      backward[to] = from;
    }
    return true;
  }
}

